'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ext = (url,title) => `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a>`;
const list = items => `<ul>${items.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`;
let saved;try{saved=JSON.parse(localStorage.getItem('research-fieldguide-v1')||'{}')}catch{saved={}}
const state={done:{},lesson:0,steps:{seo:0,leads:0,news:0},plan:{name:'My first research agent',usecase:'news',audience:'A small go-to-market team',question:'What material changes did our three competitors make this week?',sources:'Official product pages, pricing pages, changelogs, approved internal documents',budget:8,review:'All external actions require review'},notes:{},...saved};
let section='start',nodeIndex=2,traceStep=0,rag={q:'crm',mode:'hybrid',k:3,fresh:true},quizIndex=0;
function persist(){try{localStorage.setItem('research-fieldguide-v1',JSON.stringify(state))}catch{ $('.save-state').textContent='Progress is session-only'}updateProgress()}
function updateProgress(){const n=Object.values(state.done).filter(Boolean).length;$('#overallText').textContent=`Build checklist: ${n} of 32`;$('#overallBar').style.width=`${n/32*100}%`}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('Copied to clipboard')}catch{toast('Copy unavailable. Select the text to copy manually.')}}
function pageIntro(num,title,sub){return `<div class="page-intro"><div class="eyebrow">${num}</div><h1>${title}</h1><p class="lead">${sub}</p></div>`}
const nodes=[
 {icon:'⌁',name:'The question',color:'yellow',sub:'A decision, scope & finish line',role:'Define the contract',text:'Give the system a specific decision to support, the audience, a time window, allowed sources, and an output format. “Research competitors” needs a clearer finish line.',build:'Store a task object: question, entities, date range, source policy, required fields, tool budget, and approval policy.'},
 {icon:'▤',name:'The evidence',color:'blue',sub:'Your knowledge + the live web',role:'Retrieve what matters',text:'RAG retrieves relevant passages from your knowledge base. Web tools supply new information. Preserve source URLs, original text, dates, document versions, and permission metadata.',build:'Start with a curated corpus and keyword search. Compare embeddings, hybrid retrieval, and reranking against the same test questions.'},
 {icon:'✳',name:'The researcher',color:'lilac',sub:'Plan → act → observe → adapt',role:'Give judgment a bounded loop',text:'The model uses observations to choose its next research action. It can ask a better query, read an authoritative page, compare sources, or stop when the required evidence is present.',build:'One model with a small tool set is a useful starting point. The harness checks arguments, limits tool calls, saves progress, and enforces permissions.'},
 {icon:'✓',name:'The checks',color:'peach',sub:'Support, dates & permission',role:'Test the result before using it',text:'A fluent answer can still be wrong. Check whether each claim is supported by its cited passage, whether sources are current enough, and whether the output answers the original question.',build:'Use code for schemas, dates, duplicates, permissions, and calculations. Use expert review for nuanced quality. Keep facts separate from inferences.'},
 {icon:'↗',name:'The deliverable',color:'mint',sub:'A brief, a demo, a decision',role:'Produce something a person can use',text:'Return a concise result with evidence, uncertainty, and next actions. An incomplete report with explicit gaps is more useful than an unsupported conclusion.',build:'Save a draft and its evidence map. Put sending, publishing, and production updates behind the appropriate review and execution controls.'}
];
function flow(interactive=true){return `<div class="flow">${nodes.map((n,i)=>`<button class="node ${n.color} ${interactive&&nodeIndex===i?'selected':''}" data-node="${i}" aria-label="Explore ${esc(n.name)}"><span class="node-icon">${n.icon}</span><strong>${n.name}</strong><small>${n.sub}</small></button>`).join('')}</div>`}
function harness(){return `<div class="harness-bar"><b>the harness holds it all together</b><span>Permissions</span><span>State & memory</span><span>Budgets & retries</span><span>Traces & evaluations</span></div>`}
function heroArt(){return `<svg viewBox="0 0 420 280" role="img" aria-label="Hand-drawn notebook showing evidence going into a research agent and a cited brief coming out"><g fill="none" stroke="#50624f" stroke-width="1.5" stroke-linecap="round"><path d="M20 99 Q16 84 28 82 L112 78 Q122 79 121 92 L119 161 Q118 169 109 168 L25 172 Z" fill="#e7eef8"/><path d="M27 84 L115 83 115 165 22 169" opacity=".3"/><path d="M35 105 Q66 101 102 104 M35 117 L96 116 M36 129 L85 127 M36 141 L97 139"/><path d="M129 124 Q153 116 168 126 M160 117 L169 126 159 131"/><path d="M174 64 Q172 54 185 57 L270 60 Q280 59 277 72 L280 173 Q276 182 267 179 L182 177 Q171 175 174 164 Z" fill="#eee8f5"/><path d="M179 63 L272 65 276 174 180 173" opacity=".3"/><path d="M220 90 L220 135 M198 111 L244 111 M205 96 L238 128 M238 95 L205 128" stroke-width="2"/><circle cx="220" cy="111" r="12" fill="#ede8f5"/><path d="M287 121 Q305 112 322 122 M314 113 L324 122 314 128"/><path d="M329 78 L394 83 398 159 325 156 Z" fill="#e4f1e6"/><path d="M341 99 L384 101 M342 113 L379 114 M341 126 L365 127"/><path d="M345 143 l5 5 11-12"/><path d="M225 185 Q227 215 165 210 Q126 205 128 175 M121 181 L128 174 133 182" stroke-dasharray="4 4"/><path d="M48 53 Q111 22 168 42 M159 35 L169 42 157 45" stroke="#9aa78d"/><path d="M315 203 Q350 208 372 178 M364 180 L373 177 371 187" stroke="#9aa78d"/></g><g font-family="Caveat, cursive" fill="#536e50" text-anchor="middle"><text x="71" y="198" font-size="22" transform="rotate(-5 71 198)">real evidence</text><text x="224" y="157" font-size="22">your agent</text><text x="361" y="66" font-size="21" transform="rotate(5 361 66)">useful output</text><text x="217" y="243" font-size="21" transform="rotate(-3 217 243)">check, learn, improve ↺</text><text x="106" y="28" font-size="18">show your work!</text></g></svg>`}
function renderStart(){return `<section class="hero"><div><div class="eyebrow">THE BUILDER’S MASTERCLASS · EDITION 02</div><h1>Understand the system.<br>Build it.<br><span class="handwritten">Defend your decisions.</span></h1><p class="lead">Go from a sketch to a working research agent. Trace APIs and MCP, run the code, debug failures, and explain how the system creates business value.</p><div class="hero-actions"><a class="button primary" href="#protocol">Explore APIs & MCP <span>→</span></a><a class="button" href="#build">Run your first integration</a></div></div><div class="hero-art">${heroArt()}</div></section><div class="section-head"><h2>One system. Many kinds of research.</h2><p>Click any part to look inside.</p></div><div class="paper diagram"><div class="diagram-head"><span class="hand">The anatomy of a research agent</span><small>FOLLOW THE EVIDENCE →</small></div>${flow(false)}${harness()}</div><div class="section-head"><h2>Pick something worth building.</h2><p>3 blueprints · 24 practical steps</p></div><div class="path-grid">${Object.entries(BLUEPRINTS).map(([id,b],i)=>`<a class="path-card ${b.accent}" href="#${id}"><span class="mini-num">0${i+1} / the blueprint</span><span class="corner">${['⌕','↗','◷'][i]}</span><h3>${['AEO & SEO<br>research agent','Lead generation.<br>Demos that fit.','Your daily<br>intelligence briefing'][i]}</h3><p>${['Find content gaps. Ground recommendations in evidence.','Turn account research into an accurate, relevant product story.','Track meaningful changes across news, data, and competitors.'][i]}</p><span class="path-link">Open the build guide →</span></a>`).join('')}</div><div class="note-strip"><span class="hand">A little theory. A lot of doing.</span><span>Inspired by your saved learning roadmaps. Every module ends with an artifact, a test, and an explanation you can use in an interview.</span></div><div class="twocol"><div class="panel paper"><h3>New to agents?</h3><p>Start with the eight foundation modules. You’ll learn the difference between a model, a workflow, RAG, and the harness that makes an agent reliable.</p><a href="#learn">Learn by building →</a></div><div class="panel paper"><h3>Preparing for Monaco?</h3><p>Practice scoping a customer problem, tracing one account through a system, and defending your evaluation and rollout decisions.</p><a href="#interview">Practice defending your decisions →</a></div></div>`}
function renderArchitecture(){const n=nodes[nodeIndex];return `${pageIntro('02 / SEE THE SYSTEM','A research agent, unfolded.','Start with the flow. Then click a component to see what it does, what to build, and what can go wrong.')}<div class="paper diagram"><div class="diagram-head"><span class="hand">From question → evidence → useful action</span><small>CLICK TO EXPLORE</small></div>${flow()}<div class="architecture-bottom"><button class="node blue" data-detail="storage"><strong>▱ Evidence & run state</strong><small>Source snapshots · claim IDs<br>Progress · versions · approvals</small></button><button class="node yellow" data-detail="tools"><strong>⚒ A small tool belt</strong><small>Search · fetch · retrieve<br>Compare · calculate · save draft</small></button><button class="node peach" data-detail="evals"><strong>◎ Observe & evaluate</strong><small>Traces · errors · quality<br>Cost · latency · usefulness</small></button></div>${harness()}</div><div id="nodeDetail" class="detail-panel"><div class="label">${esc(n.role).toUpperCase()}</div><h3>${n.name}</h3><p>${n.text}</p><p><b>Build it:</b> ${n.build}</p></div><div class="section-head"><h2>Watch one investigation unfold.</h2><p>Illustrative trace · no live tools</p></div><div class="paper panel"><ol class="trace-list" id="traceList"></ol><div class="stepper"><button class="button primary" id="traceNext">Next action →</button><button class="button" id="traceReset">Restart trace</button></div></div><div class="callout yellow"><span class="hand">What should the model decide?</span>The next useful research question. Code should enforce access, budgets, output schemas, and action permissions. A prompt alone is not an access-control system.</div><div class="twocol"><div class="paper panel"><h3>Workflow + RAG</h3><p>A fixed path: retrieve passages → draft an answer → validate. Useful when the evidence sources and sequence are predictable.</p><p><b>Example:</b> Answer a question about approved product capabilities.</p></div><div class="paper panel"><h3>Agent + RAG</h3><p>An adaptive path: inspect evidence → choose another query or tool → gather more evidence → finish within a budget.</p><p><b>Example:</b> Investigate a competitor’s changed pricing and what it means.</p></div></div><a class="source-link" href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noopener">Read: Anthropic’s architecture patterns ↗</a>`}
const trace=[['Receive the task','Compare SignalDesk’s current pricing with its earlier published price.'],['Retrieve the prior snapshot','Evidence E1: fictional price $49/user/month, effective September 1.'],['Fetch the current source','Evidence E2: fictional price $59/user/month, effective November 1.'],['Check comparability','Same product tier, USD, per-user, monthly billing. A change in units would block comparison.'],['Calculate in code','(59 − 49) / 49 × 100 = 20.4%. The model does not need to do the arithmetic.'],['Write a supported finding','Price rose from $49 to $59, +20.4% [E1, E2]. Impact on actual customers depends on contract terms.'],['Save the draft and stop','Persist evidence and completed steps. A reviewer decides whether the finding belongs in the briefing.']];
function paintTrace(){if(!$('#traceList'))return;$('#traceList').innerHTML=trace.map((t,i)=>`<li class="${i>traceStep?'dim':''}"><b>${i< traceStep?'✓ ':i===traceStep?'→ ':''}${t[0]}</b><small>${i<=traceStep?t[1]:'Waiting for the preceding step.'}</small></li>`).join('');$('#traceNext').disabled=traceStep===trace.length-1;$('#traceNext').textContent=traceStep===trace.length-1?'Investigation complete':'Next action →'}
function renderLearn(){const l=LESSONS[state.lesson];return `${pageIntro('03 / LEARN BY BUILDING','The foundations, one useful piece at a time.','Build one small system through all eight modules. Each milestone gives you something to inspect and explain.')}<div class="lesson-layout"><div class="lesson-menu">${LESSONS.map((x,i)=>`<button class="lesson-button ${i===state.lesson?'active':''}" data-lesson="${i}" aria-pressed="${i===state.lesson}"><span class="step-num">${String(i+1).padStart(2,'0')}</span>${esc(x.title)}${state.done['lesson'+i]?'<span class="done">✓</span>':''}</button>`).join('')}</div><article class="paper lesson-content"><div class="eyebrow">${esc(l.kicker)}</div><h2>${esc(l.title)}</h2>${l.explanation.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="hand">Build this ↓</div>${list(l.build)}<div class="step-output"><strong>TEST YOUR WORK</strong><p>${esc(l.test)}</p></div><div class="example">“${esc(l.explain)}”</div><a class="source-link" href="${l.source.url}" target="_blank" rel="noopener">${esc(l.source.title)} ↗</a><div class="step-footer"><label class="checkline"><input type="checkbox" data-done="lesson${state.lesson}" ${state.done['lesson'+state.lesson]?'checked':''}> I built and checked this milestone</label><button class="button primary" data-next-lesson>${state.lesson===7?'Choose a blueprint →':'Next module →'}</button></div></article></div><div class="callout yellow"><span class="hand">You can build before training a neural network.</span>For an API-based research agent, start with Python or JavaScript, HTTP/JSON, data handling, retrieval, and testing. The deeper ML curriculum is useful when you want to understand or train the underlying models.</div><div class="section-head"><h2>A small dictionary for the journey.</h2></div><dl class="glossary">${GLOSSARY.map(g=>`<div><dt>${esc(g.term)}</dt><dd>${esc(g.definition)}</dd></div>`).join('')}</dl>`}
function renderBlueprint(id){const b=BLUEPRINTS[id],i=state.steps[id]||0,s=b.steps[i];return `${pageIntro('THE BLUEPRINT / '+({seo:'01',leads:'02',news:'03'}[id]),esc(b.title),esc(b.subtitle))}<div class="build-inputs"><div><b>START WITH</b>${esc(b.inputs.slice(0,2).join(' + '))}</div><div><b>PRODUCE</b>${esc(b.output)}</div><div><b>FIRST DEPLOYMENT</b>A small corpus, one bounded workflow, and a human-reviewed draft.</div></div><div class="step-layout"><div class="step-menu">${b.steps.map((x,j)=>`<button class="step-button ${i===j?'active':''}" data-step="${j}" aria-pressed="${i===j}"><span class="step-num">${j+1}</span>${esc(x.title)}${state.done[id+j]?'<span class="done">✓</span>':''}</button>`).join('')}</div><article class="paper lesson-content"><div class="eyebrow">STEP ${i+1} OF 8</div><h2>${esc(s.title)}</h2><p>${esc(s.why)}</p><div class="hand">Here’s what to do</div><ol>${s.actions.map(a=>`<li>${esc(a)}</li>`).join('')}</ol><div class="step-output"><strong>YOUR OUTPUT</strong><p>${esc(s.output)}</p></div><div class="example">${esc(s.example)}</div><div class="hand">Before moving on</div><p>${esc(s.check)}</p><div class="step-footer"><label class="checkline"><input type="checkbox" data-done="${id+i}" ${state.done[id+i]?'checked':''}> Built & checked</label><button class="button primary" data-next-step>${i===7?'Customize my build →':'Next step →'}</button></div></article></div><div class="section-head"><h2>The parts that make this work.</h2></div><div class="twocol"><div class="paper panel"><h3>Where RAG fits</h3><p>${esc(b.rag)}</p><div>${b.tools.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></div><div class="paper panel"><h3>Measure the useful outcome</h3>${list(b.metrics)}<p class="tiny" style="margin-top:15px">Set thresholds with the customer based on the cost of errors. Keep an offline test set and compare the pilot with a baseline.</p></div></div><details class="details"><summary>Failure drill: what should the agent do?</summary><div><p>${esc(b.failure.scenario)}</p><div class="callout mint">${esc(b.failure.answer)}</div></div></details><details class="details"><summary>Inspect a sample deliverable · fictional SignalDesk example</summary><div><pre>${esc(b.sampleOutput)}</pre></div></details><details class="details"><summary>Copy the task prompt for this build</summary><div><div class="code-head"><p class="no-margin">Pair this prompt with the actual tools, permissions, and evaluation cases.</p><button class="button small" data-copy-prompt>Copy prompt</button></div><pre>${esc(b.prompt)}</pre></div></details><div class="callout ${b.accent}"><span class="hand">The next useful artifact</span>Turn this blueprint into your own specification. <a href="#kit" data-kit-usecase="${id}">Open the build kit →</a></div><div class="tiny">Further reading: ${b.sources.map(s=>ext(s.url,s.title)).join(' · ')}</div>`}
const docs=[
 {id:'P1',title:'SignalDesk product guide v2',date:'2026-11-01',text:'The released product supports HubSpot. The Salesforce connector is planned and is not available.',kind:'Approved product documentation',fresh:true},
 {id:'P2',title:'Old pricing snapshot',date:'2026-09-01',text:'SignalDesk Pro costs USD 49 per user per month on monthly billing. This version is superseded.',kind:'Historical snapshot',fresh:false},
 {id:'P3',title:'Current pricing snapshot',date:'2026-11-01',text:'SignalDesk Pro costs USD 59 per user per month on monthly billing, effective November 1.',kind:'Approved pricing documentation',fresh:true},
 {id:'P4',title:'Regional hosting specification',date:'2026-10-20',text:'An EU tenant can choose the Frankfurt hosting region for storage and processing of workspace records.',kind:'Approved infrastructure documentation',fresh:true},
 {id:'P5',title:'Old sales blog',date:'2026-06-01',text:'SignalDesk CRM integration connects your sales workflow. Salesforce support is expected later this year.',kind:'Superseded marketing page',fresh:false},
 {id:'P6',title:'Funding announcement',date:'2026-11-12',text:'Fictional account Northstar Labs announced a new financing round. This says nothing about SignalDesk integrations.',kind:'Public announcement',fresh:true}
];
const scenarios={crm:{label:'Does SignalDesk support Salesforce today?',keyword:['P5','P1'],semantic:['P1','P5'],hybrid:['P1','P5']},price:{label:'What is the current monthly price of Pro?',keyword:['P2','P3'],semantic:['P3','P2'],hybrid:['P3','P2']},region:{label:'Can customers keep their data in Europe?',keyword:[],semantic:['P4'],hybrid:['P4']},unknown:{label:'Does SignalDesk support HIPAA-regulated workflows?',keyword:[],semantic:[],hybrid:[]}};
function renderRag(){return `${pageIntro('04 / THE RAG PLAYGROUND','Let the evidence change the answer.','Retrieval-augmented generation finds relevant material before writing. Explore the retrieval choices—and why a plausible answer still needs checks.')}<div class="live-note">TEACHING SIMULATION · Fictional documents and hand-authored rankings. No live model, embeddings, web search, or private data is used here.</div><div class="paper panel"><div class="controls"><label class="field">Research question<select id="ragQuery">${Object.entries(scenarios).map(([k,s])=>`<option value="${k}" ${rag.q===k?'selected':''}>${s.label}</option>`).join('')}</select></label><label class="field">Retrieval method<select id="ragMode">${['keyword','semantic','hybrid'].map(k=>`<option value="${k}" ${rag.mode===k?'selected':''}>${k[0].toUpperCase()+k.slice(1)}</option>`).join('')}</select></label><label class="field">Passages to keep<select id="ragK">${[1,2,3].map(k=>`<option value="${k}" ${rag.k===k?'selected':''}>Top ${k}</option>`).join('')}</select></label></div><label class="toggle"><input id="ragFresh" type="checkbox" ${rag.fresh?'checked':''}> Exclude superseded documents when answering current-state questions</label><div class="retrieval-flow"><span>Question</span>→<span>Access + version filters</span>→<span>Retrieve</span>→<span>Evidence check</span>→<span>Answer</span></div><div id="ragResults"></div></div><div class="callout yellow"><span class="hand">Try these three experiments</span>1. Turn off the version filter, choose Keyword and Top 1 for pricing. Notice the stale evidence warning.<br>2. Ask about Europe with Keyword, then Semantic. Similar meaning does not require identical words.<br>3. Ask the unsupported HIPAA question. The correct behavior is an evidence gap.</div><div class="section-head"><h2>Chunks need their context.</h2><p>A tiny fragment can hide a big assumption.</p></div><div class="paper panel"><label class="toggle"><input type="checkbox" id="chunkContext"> Keep the heading, entity, date, and units with the passage</label><div class="chunk-demo" id="chunkDemo"></div></div><div class="section-head"><h2>Build the two lanes separately.</h2></div><div class="twocol"><div class="paper panel"><span class="hand">01 / prepare the library</span><p>Fetch approved sources → parse readable text → deduplicate → split by meaning → attach metadata → create keyword and vector indexes → refresh or delete changed material.</p><p><b>Inspect:</b> document title, section, original passage, source URL, publication date, retrieval date, version, and access permissions.</p></div><div class="paper panel"><span class="hand">02 / answer a question</span><p>Authenticate → apply scope and access filters → retrieve candidates → deduplicate and rerank → select evidence → generate → validate claims and citations.</p><p><b>Inspect:</b> the actual retrieved passages. A missing fact is often a retrieval problem before it is a prompting problem.</p></div></div><details class="details"><summary>Practical tuning checklist</summary><div>${list(['Compare a keyword baseline with vector and hybrid retrieval using the same labeled questions.','Try section-based chunks and several chunk sizes. Keep tables, units, and qualifiers together.','Use the same compatible embedding model for the query and index; version and rebuild the index when changing it.','Try a candidate pool such as 20 passages, then rerank to five. These are experiment settings, not universal defaults.','Measure whether the required evidence appears, whether it is correctly cited, and how much irrelevant context is included.','Apply identity and permission rules before model context and to caches. A prompt cannot grant access.'])}</div></details><div class="tiny">Primary references: ${ext('https://www.anthropic.com/research/contextual-retrieval','Contextual retrieval')} · ${ext('https://learn.microsoft.com/en-us/azure/search/vector-search-how-to-chunk-documents','Chunking')} · ${ext('https://learn.microsoft.com/en-us/azure/search/search-document-level-access-overview','Access control')}</div>`}
function paintRag(){const ranks=scenarios[rag.q][rag.mode];const found=ranks.map(id=>docs.find(d=>d.id===id)).filter(d=>!rag.fresh||d.fresh).slice(0,rag.k);let status='SUPPORTED',answer='',detail='';const has=id=>found.some(d=>d.id===id);if(!found.length){status='INSUFFICIENT EVIDENCE';answer=rag.q==='unknown'?'The knowledge base does not establish support for HIPAA-regulated workflows. Ask for reviewed compliance documentation; do not infer compliance from a security or hosting feature.':'No relevant passage was found by this retrieval configuration. Try semantic or hybrid search, then inspect the actual evidence.';detail='An empty result is not proof that the capability is absent.'}else if(rag.q==='crm'){if(has('P1')){answer='Salesforce is not released in the current product guide. HubSpot is supported; Salesforce remains planned. [P1]';detail=has('P5')?'The older blog’s expectation does not establish current availability. Prefer the versioned product guide.':'A negative answer can be fully supported. Use a HubSpot demo or clearly label a Salesforce concept as a mock-up.'}else{status='STALE / INSUFFICIENT';answer='This older blog describes an expectation, not a released capability. Current support cannot be established from this passage. [P5]';detail='Re-fetch or retrieve the current product guide before building a demo.'}}else if(rag.q==='price'){if(has('P3')){answer='The current fictional price is USD 59 per user per month on monthly billing, effective November 1. [P3]';detail=has('P2')?'The historical USD 49 price [P2] is useful for a comparison, not as the current answer. The increase is 20.4%, assuming the same tier and billing terms.':'Preserve currency, billing period, tier, and effective date with any price.'}else{status='STALE / INSUFFICIENT';answer='The retrieved price is USD 49, but its source is superseded. It cannot establish the current price. [P2]';detail='The version filter or a better-ranked current source prevents a confident stale answer.'}}else{answer='The specification offers an EU tenant a Frankfurt region for workspace-record storage and processing. [P4]';detail='That evidence supports a regional hosting option. It does not establish every data-residency or compliance requirement; confirm the exact customer scope.'}$('#ragResults').innerHTML=`<div class="results"><div><h3>Retrieved evidence <span class="muted tiny">${found.length} passage${found.length===1?'':'s'}</span></h3>${found.map((d,i)=>`<article class="result-item"><h4>${i+1}. ${d.title} <span class="tag">${d.id}</span></h4><p>${d.text}</p><small>${d.kind} · ${d.date}${!d.fresh?' · SUPERSEDED':''}</small></article>`).join('')||'<div class="result-item"><p>No passage cleared the relevance and version filters.</p></div>'}<p class="tiny muted">Permission filtering is always applied in the design. This public fixture contains no private documents.</p></div><div class="answer"><span class="status ${status==='SUPPORTED'?'':'warn'}">${status}</span><h3>The answer we can defend</h3><p>${answer}</p><small>${detail}</small></div></div>`}
function paintChunk(){const on=$('#chunkContext').checked;$('#chunkDemo').innerHTML=`<div class="chunk"><b>RETRIEVED PASSAGE</b>${on?'SignalDesk Pro · USD per user/month · monthly billing · effective Nov 1, 2026 · source P3<br>':''}The price is 59.</div><div class="chunk"><b>${on?'CONTEXT PRESERVED':'WHAT IS MISSING?'}</b>${on?'Now we can identify the product, currency, period, version, and supporting source. Compare like-for-like before calculating a change.':'Which product? Which currency? Per user or per account? Monthly or annual? When is it effective? Retrieval without context is not enough.'}</div>`}
const harnessCode=`# Architecture pseudocode — implement the adapters in your stack\nstate = load_or_create_run(task_id)\nwhile within_budget(state):\n    action = model.choose(task, state, allowed_tools)\n    if action.type == "finish":\n        break\n    validate_tool_and_args(action, caller_permissions)\n    result = execute_with_bounded_retry(action)\n    persist_tool_result_and_evidence(state, result)\n    update_remaining_questions(state)\n\ndraft = synthesize_with_claim_source_mapping(state.evidence)\nchecks = validate_schema_sources_dates_numbers(draft)\nreturn supported_findings_and_explicit_gaps(draft, checks)\n\n# External writes go through a separate approval/execution path.\n# On ambiguous timeouts, reconcile action status before retrying.`;
function getPlan(){const budget=Math.min(100,Math.max(1,Math.trunc(Number(state.plan.budget)||1)));return {...state.plan,budget,tool_budget:budget,architecture:'One bounded research agent with retrieval; deterministic validation and approval gates',evidence_schema:['source_id','canonical_url','title','original_text','published_at','retrieved_at','version','allowed_principals'],output_schema:['finding','evidence_ids','evidence_status','interpretation','open_questions','next_action'],evaluation_cases:['supported question','unanswerable question','stale source','conflicting sources','unauthorized document','retrieved prompt injection','tool timeout'],completed_milestones:Object.keys(state.done).filter(k=>state.done[k])}}
function renderKit(){const p=state.plan;return `${pageIntro('YOUR BUILD KIT','Turn the sketch into a specification.','Make the decisions explicit. Export your plan, use the prompt template, and start with a runnable local evidence pipeline.')}<div class="twocol"><form class="paper panel" id="planForm"><label class="field">Project name<input name="name" value="${esc(p.name)}"></label><label class="field">Starting blueprint<select name="usecase">${Object.entries(BLUEPRINTS).map(([k,b])=>`<option value="${k}" ${p.usecase===k?'selected':''}>${esc(b.title)}</option>`).join('')}</select></label><label class="field">Who will use the result?<input name="audience" value="${esc(p.audience)}"></label><label class="field">What decision or question should it answer?<textarea name="question">${esc(p.question)}</textarea></label><label class="field">Approved sources<textarea name="sources">${esc(p.sources)}</textarea></label><label class="field">Maximum tool calls per run<input name="budget" type="number" min="1" max="100" value="${p.budget}"><small>Illustrative limit. Set a separate spend limit and deadline in your application.</small></label><label class="field">Review boundary<select name="review">${['All external actions require review','Research drafts only; no external actions','Approved low-risk actions; exceptions require review'].map(x=>`<option ${p.review===x?'selected':''}>${x}</option>`).join('')}</select></label><p class="tiny muted no-margin">Saved on this device as you edit. This guide does not connect services or schedule jobs.</p></form><div><div class="paper panel"><div class="code-head"><h3>Your task contract</h3><button class="button small" id="copyPlan">Copy JSON</button></div><pre id="planCode"></pre><button class="button primary" id="exportPlan" style="margin-top:18px">Download my build plan ↓</button></div></div></div><div class="section-head"><h2>A practical first implementation.</h2><p>Small enough to understand end to end.</p></div><div class="paper panel"><table><thead><tr><th>Piece</th><th>Start here</th><th>Grow when needed</th></tr></thead><tbody><tr><td>Application</td><td>One Python or TypeScript service</td><td>API + background workers for long runs</td></tr><tr><td>Sources</td><td>Approved local files and source snapshots</td><td>Search/fetch APIs and source-specific refresh jobs</td></tr><tr><td>Retrieval</td><td>Lexical baseline on a small corpus</td><td>Embeddings + hybrid search + reranking</td></tr><tr><td>Run state</td><td>SQLite and unique run/action IDs</td><td>Managed database, queues, durable execution</td></tr><tr><td>Model</td><td>One model with schema-constrained tools</td><td>Model routing after quality/cost evaluation</td></tr><tr><td>Interface</td><td>Inspect report, evidence, trace, and approve</td><td>Feedback, audit history, team permissions</td></tr><tr><td>Recurring research</td><td>Manual runs and a delivery ledger</td><td>Scheduler with timezone, overlap, deduplication, retries</td></tr></tbody></table></div><div class="twocol" style="margin-top:22px"><div class="paper panel"><h3>Download the Python build kit</h3><p>Start offline with lexical retrieval, citations, run-state persistence, fictional documents, and regression tests. Then try the optional live-model tool loop over the same evidence.</p><p>The offline path uses the standard library. The live path requires the Anthropic SDK, a model ID, and your own server-side API key. Setup and limitations are in the README.</p><a class="button primary" href="research-agent-starter.zip" download>Get the Python starter ↓</a><pre>python3 research_agent.py --query "Does SignalDesk support HubSpot?"</pre></div><div class="paper panel"><h3>Production release checklist</h3><div class="checklist">${['Secrets stay server-side; tools have minimum necessary access.','Retrieved documents and caches enforce tenant permissions.','All material claims have supporting, dated evidence.','Unknowns, conflicts, and unsupported questions are tested.','Runs persist state and stop at time, tool, and spend budgets.','Retries reconcile external writes and prevent duplicate actions.','Traces record versions, evidence, cost, latency, and failures.','A named owner can pause runs, review errors, and roll back.'].map((t,i)=>`<label><input type="checkbox" data-release="${i}" ${state.release?.[i]?'checked':''}>${t}</label>`).join('')}</div></div></div><details class="details"><summary>Go from the offline baseline to a live agent</summary><div><ol><li>Run the offline query and evaluation checks. Inspect the original passages and source IDs.</li><li>Create a Python virtual environment and install the Anthropic SDK, following the starter README.</li><li>Set ANTHROPIC_API_KEY and ANTHROPIC_MODEL in your local or server environment. Keep keys out of browser code.</li><li>Run live_agent.py. The model can request retrieve_knowledge; validated tool results are returned to the next model turn.</li><li>Inspect the trace and final source IDs. ID validation checks that a citation exists; human or semantic evaluation must still check whether it supports the claim.</li><li>Add approved web-search and fetch adapters only after the local loop behaves well. Preserve provenance and apply the same permission, budget, and error rules.</li></ol><p>The live example is bounded and uses the fictional local corpus. It does not perform live web searches or external writes. The live API was not exercised during guide creation; mocked tool-loop tests cover the integration logic.</p></div></details><details class="details"><summary>Inspect the agent loop pseudocode</summary><div><button class="button small" id="copyLoop">Copy pseudocode</button><pre>${esc(harnessCode)}</pre></div></details><div class="section-head"><h2>Model the economics.</h2><p>Your assumptions, not a price quote.</p></div><div class="paper panel"><div class="controls"><label class="field">Runs per month<input id="calcRuns" type="number" min="0" value="300"></label><label class="field">API + tools per run ($)<input id="calcApi" type="number" min="0" step=".01" value="0.20"></label><label class="field">Human review minutes per run<input id="calcMinutes" type="number" min="0" step=".5" value="2"></label></div><label class="field">Reviewer cost per hour ($)<input id="calcRate" type="number" min="0" value="50"></label><div class="metric-grid" id="costResults"></div><p class="tiny muted" style="margin-top:15px">Includes only the entered variable costs. Add hosting, data subscriptions, setup, support, and failure/rework costs for a complete business case.</p></div>`}
function paintPlan(){if($('#planCode'))$('#planCode').textContent=JSON.stringify(getPlan(),null,2)}
function exportPlan(){const b=BLUEPRINTS[state.plan.usecase];const text=`# ${state.plan.name}\n\n## Task contract\n\n${JSON.stringify(getPlan(),null,2)}\n\n## Build steps\n\n${b.steps.map((s,i)=>`${i+1}. ${s.title}\n${s.actions.map(a=>'   - '+a).join('\n')}\n   Output: ${s.output}\n   Check: ${s.check}`).join('\n\n')}\n\n## Task prompt\n\n${b.prompt}\n\n## Measure\n\n${b.metrics.map(m=>'- '+m).join('\n')}\n\n## References\n\n${b.sources.map(s=>'- '+s.title+': '+s.url).join('\n')}\n\nLearning guide: https://research-agent-fieldguide-mary.aglow-stoat-1099.chatgpt.site\n`;const blob=new Blob([text],{type:'text/markdown'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='my-research-agent-plan.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Your build plan is downloaded')}
function paintCost(){const n=id=>Math.max(0,Number($(id).value)||0);const runs=n('#calcRuns'),api=runs*n('#calcApi'),review=runs*n('#calcMinutes')/60*n('#calcRate');$('#costResults').innerHTML=[['$'+api.toFixed(0),'API + tools / month'],['$'+review.toFixed(0),'Review / month'],['$'+(api+review).toFixed(0),'Combined variable cost / month']].map(([a,b])=>`<div class="metric"><strong>${a}</strong><span>${b}</span></div>`).join('')}
const cases=[{title:'The Monaco-style deployment case',prompt:'A B2B team wants more qualified pipeline without hiring. Research is slow, CRM data is inconsistent, and the sales leader wants autonomous outreach. Design the first useful agent deployment.',checks:['Defined qualified pipeline and the current funnel bottleneck','Chose a narrow pilot and explained why','Mapped one account from inputs to output','Separated model judgment from deterministic controls','Specified evidence, tools, state, and recovery','Defined offline evaluations and business success','Explained review, rollout, adoption, and ownership'],answer:'Begin with discovery: is the constraint account volume, targeting, messaging, or conversion? A sensible candidate pilot is account research and a grounded demo draft. Use a bounded agent to investigate fit; code enforces suppression and duplicate checks. Retrieve approved product capabilities, keep pain points labeled as hypotheses, and test demo interactions. Measure accepted opportunities and rep time including review. Expand only when evidence from the pilot supports the decision.'},{title:'A plausible but wrong demo',prompt:'The prospect uses Salesforce. Your product supports HubSpot today, and a roadmap mentions Salesforce. The agent generates a working-Salesforce demo claim. Diagnose and redesign.',checks:['Distinguished roadmap from released capability','Traced the unsupported claim to its source','Fixed document versioning or retrieval policy','Added a claim-to-capability validation check','Used a clearly labeled mock-up or an honest alternative','Added the failure to the regression set'],answer:'Inspect the retrieved passages and version metadata. A roadmap is not evidence of released functionality. Ground the demo in a versioned capability catalog; require each feature claim to map to a current entry. Either choose a supported workflow or label a concept as a nonfunctional mock-up and have a rep review it. Test future roadmap claims as explicit negative cases.'},{title:'The noisy daily briefing',prompt:'Your briefing repeats yesterday’s story, treats a newly republished article as a new event, and reports a price increase caused only by a switch from monthly to annual billing. What changes?',checks:['Separated event, publication, and retrieval dates','Clustered duplicate stories under one event','Kept previous snapshots and a delivery ledger','Compared the same tier, units, currency, and period','Reported unresolved contradictions','Measured material-change precision and missed events'],answer:'Store event time separately from publication and fetch time. Cluster related coverage, retain source snapshots, and compare normalized facts rather than page text alone. Price comparisons must match product tier, currency, unit, and billing basis. Keep a per-event delivery ledger; a rerun should update an event, not send duplicates. Evaluate both false alerts and missed material changes.'},{title:'The SEO shortcut',prompt:'The agent recommends “add FAQ schema and split every page into tiny chunks to guarantee AI citations.” How do you respond?',checks:['Rejected the unsupported visibility guarantee','Distinguished retrieval chunks from public page structure','Checked official search guidance','Prioritized useful original content and discoverability','Proposed a measurable experiment with a baseline'],answer:'Google does not promise AI visibility from a special schema. Index chunking is an internal RAG choice, not a reason to fragment public content. Check crawl/indexing eligibility and whether visible content answers a real user need. Use appropriate structured data that matches the page. Evaluate dated observations and qualified outcomes without claiming causality from a single answer snapshot.'}];
function renderPractice(){const c=cases[quizIndex];return `${pageIntro('INTERVIEW PRACTICE','Explain the choices behind the diagram.','Use these hypothetical cases to rehearse a live discussion. They are practice scenarios informed by the work, not verified Monaco interview questions.')}<div class="tabs">${cases.map((c,i)=>`<button class="tab ${quizIndex===i?'active':''}" data-case="${i}">Case ${i+1}: ${['Deployment','Demo accuracy','Daily briefing','AEO / SEO'][i]}</button>`).join('')}</div><div class="paper practice-case yellow"><span class="case-label">HYPOTHETICAL CASE · THINK ALOUD</span><h2 style="margin-top:10px">${c.title}</h2><blockquote>${c.prompt}</blockquote><label class="field">Your opening, questions, and design decisions<textarea id="caseNotes" placeholder="Start with the business outcome. What would you clarify before designing?" style="min-height:150px">${esc(state.notes[quizIndex]||'')}</textarea><small>Your notes stay in this browser.</small></label></div><div class="twocol" style="margin-top:22px"><div class="paper panel"><h3>Self-review rubric</h3><div class="checklist">${c.checks.map((t,i)=>`<label><input type="checkbox" data-rubric="${i}">${t}</label>`).join('')}</div><div class="row"><span class="tiny muted">Coverage check, not an assessment of answer quality</span><span class="score" id="caseScore">0/${c.checks.length}</span></div></div><div class="paper panel"><h3>A useful way to structure your answer</h3><p><b>1.</b> Clarify the outcome and bottleneck.<br><b>2.</b> Pick the smallest useful deployment.<br><b>3.</b> Trace one example through the system.<br><b>4.</b> Explain controls and failure recovery.<br><b>5.</b> Define evaluations and business metrics.<br><b>6.</b> Propose a rollout and expansion criteria.</p><details class="details"><summary>Reveal a strong answer outline</summary><div><p>${c.answer}</p></div></details><p class="tiny muted">Follow-up: What would make you stop, seek more evidence, or hand the task to a person?</p></div></div><div class="callout mint"><span class="hand">The question behind almost every question</span>What does the model decide, what does code enforce, what evidence supports the result, and how would you know the system is useful?</div><div class="tiny">Role context: ${ext('https://www.monaco.com/product','Monaco product')} · ${ext('https://jobs.ashbyhq.com/monaco/3e2ab0e7-db5f-4fa0-b467-a4fd0e0be508','Adjacent forward-deployed engineering role')}</div>`}
const resources=[
 ['Python foundations','Use this when functions, testing, exceptions, files, or APIs still feel unfamiliar.','https://cs50.harvard.edu/python/','Harvard CS50P'],
 ['Build a RAG application','Use the retrieval and evaluation material to turn a source collection into a citation-bearing assistant.','https://github.com/DataTalksClub/llm-zoomcamp','DataTalksClub LLM Zoomcamp'],
 ['Understand tools and agent loops','Practice observing tool results, choosing actions, and evaluating a complete task.','https://huggingface.co/learn/agents-course/unit0/introduction','Hugging Face Agents Course'],
 ['Choose an architecture','Learn chaining, routing, parallel work, orchestration, and evaluator loops; add complexity when it helps.','https://www.anthropic.com/engineering/building-effective-agents','Anthropic architecture patterns'],
 ['Connect tools with MCP','Learn the interface between an AI application and external tools or data. MCP does not replace your permissions or harness.','https://huggingface.co/learn/mcp-course/unit0/introduction','Hugging Face MCP Course'],
 ['Take the prototype to production','Use the testing, serving, monitoring, and operations material after the small system works.','https://madewithml.com/','Made With ML'],
 ['LLM application design','Study prompting, retrieval, and product evaluation as parts of a complete system.','https://fullstackdeeplearning.com/llm-bootcamp/','Full Stack Deep Learning'],
 ['Study agents in action','From your earlier bookmarks: a talk about persistent execution, tools, context, and the harness around an agent.','https://www.youtube.com/watch?v=L1OBRtfPS34&t=1087s','Lee Robinson · harness section']
];
function renderLibrary(){return `${pageIntro('THE READING ROOM','A learning path, with a purpose.','Use the resources when you need them. Keep moving one project from a small prototype to a tested, useful system.')}<div class="twocol"><article class="paper panel article-note"><div class="eyebrow">FROM YOUR FIRST LINK</div><h3>mentalium’s 12-week build roadmap</h3><p>The roadmap connects Python, model fundamentals, LLM apps, RAG, tools, and production engineering. Its strongest idea for this guide is progressing through concrete project milestones.</p><p><b>Our adaptation:</b> learn → build → test → explain. Keep one research project throughout. Its schedule assumes basic Python and selected lessons; completion time varies, and APIs or compute may cost extra.</p>${ext('https://x.com/mentalium_/status/2121991196973072831','Read the original roadmap')}</article><article class="paper panel article-note"><div class="eyebrow">FROM YOUR SECOND LINK</div><h3>shikamaru’s free AI course library</h3><p>A broad catalog spanning ML foundations, deep learning, optimization, NLP, reinforcement learning, and other fields. Many entries are historical university courses.</p><p><b>Our adaptation:</b> keep a focused builder path and an optional foundations library. The title’s degree-replacement promise is the author’s claim; the catalog is a resource list, not a verified equivalence to a degree.</p>${ext('https://x.com/shikamarutsai/status/2088918066310652358','Read the original course collection')}</article></div><div class="section-head"><h2>Your project-based learning path.</h2><p>Advance by evidence of progress.</p></div><div class="learning-path">${[['01 / get comfortable','Read files, call an API, parse JSON, and write a small test.','Artifact: a source manifest.'],['02 / retrieve evidence','Build the ingestion and retrieval lanes; preserve dates and sources.','Artifact: a cited answer.'],['03 / add agency','Give the model tools, a stop condition, and persistent run state.','Artifact: a replayable trace.'],['04 / make it dependable','Evaluate failures, add review, deploy, and monitor usefulness.','Artifact: evals + a runbook.']].map(x=>`<article><strong>${x[0]}</strong><p>${x[1]}</p><p><b>${x[2]}</b></p></article>`).join('')}</div><div class="section-head"><h2>Open the resource you need next.</h2></div><div class="resource-grid">${resources.map(r=>`<article class="resource"><h3>${r[0]}</h3><p>${r[1]}</p>${ext(r[2],r[3])}</article>`).join('')}</div><details class="details"><summary>Optional foundations: go deeper into how models work</summary><div><p>These subjects deepen your understanding; they need not block a first API-based research agent.</p>${list(['Neural networks and backpropagation: understand how parameters learn.','Transformers and tokenization: understand the model’s input and context constraints.','Training and fine-tuning: useful when you need behavior that prompting and retrieval do not provide.','ML operations: experiment tracking, deployment, drift, and reproducibility.'])}<div class="tiny">${ext('https://course.fast.ai/','fast.ai')} · ${ext('https://github.com/karpathy/nn-zero-to-hero','Karpathy')} · ${ext('https://docs.pytorch.org/tutorials/beginner/basics/intro.html','PyTorch')} · ${ext('https://huggingface.co/learn/llm-course/chapter1/1','Hugging Face LLM course')} · ${ext('https://github.com/DataTalksClub/mlops-zoomcamp','MLOps Zoomcamp')}</div></div></details><div class="section-head"><h2>Technical sources behind the guide.</h2></div><div class="paper panel"><div class="resource-grid">${[['Agent patterns','https://www.anthropic.com/engineering/building-effective-agents'],['Contextual retrieval','https://www.anthropic.com/research/contextual-retrieval'],['Long-running harnesses','https://www.anthropic.com/engineering/effective-harnesses-for-long-running-agents'],['Agent evaluations','https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents'],['RAG document chunking','https://learn.microsoft.com/en-us/azure/search/vector-search-how-to-chunk-documents'],['Document access controls','https://learn.microsoft.com/en-us/azure/search/search-document-level-access-overview'],['Google’s AI search guidance','https://developers.google.com/search/docs/fundamentals/ai-optimization-guide'],['Prompt injection defenses','https://cheatsheetseries.owasp.org/cheatsheets/LLM_Prompt_Injection_Prevention_Cheat_Sheet.html']].map(x=>`<div class="tiny">${ext(x[1],x[0])}</div>`).join('')}</div></div><div class="callout"><span class="hand">About the visual language</span>Original diagrams inspired by the clarity of ${ext('https://x.com/techyoutbe/status/2121970525442548119','Tech Fusionist’s observability architecture')} and an Excalidraw-like whiteboard style: grouped components, visible flows, and short annotations. The guide’s architecture, examples, exercises, and build paths are our synthesis.</div>`}
function render(){
  const extra=window.GUIDE_EXTENSIONS;
  section=location.hash.slice(1)||'start';
  const baseNames={start:'The Research Agent Fieldguide',architecture:'See the system',learn:'Learn by building',rag:'RAG playground',seo:'AEO / SEO researcher',leads:'Leads + custom demos',news:'Daily intelligence',kit:'Your build kit',practice:'Quick interview cases',library:'Reading room'};
  if(!baseNames[section]&&!extra?.pages[section])section='start';
  document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===section;a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});
  const title=extra?.pages[section]?.title||baseNames[section];
  $('#crumb').textContent=title.toUpperCase();
  if(extra?.pages[section])$('#main').innerHTML=extra.pages[section].render();
  else $('#main').innerHTML=section==='start'?renderStart():section==='architecture'?renderArchitecture():section==='learn'?renderLearn():section==='rag'?renderRag():BLUEPRINTS[section]?renderBlueprint(section):section==='kit'?renderKit():section==='practice'?renderPractice():renderLibrary();
  if(!extra?.pages[section])bind();
  extra?.bind(section);
  updateProgress();
  document.title=title+' · Agent Fieldguide';
  if($('#mobileJump'))$('#mobileJump').value=section;
}
function bind(){document.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>{nodeIndex=Number(b.dataset.node);if(section!=='architecture')location.hash='architecture';else{render();}});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const d={storage:['Evidence is not the same as memory','Keep original source snapshots and their metadata in an evidence store. Keep run status, completed steps, budgets, and approvals in durable operational state. Retrieval indexes can be rebuilt from source records; they should not be the only copy of your evidence.'],tools:['Make tools narrow and observable','Each tool should have a schema, a clear purpose, permission checks, structured results, and distinct errors. Separate read tools from write tools. Returning source IDs and dates makes the next step easier to verify.'],evals:['Inspect the whole task','Record the task, model and prompt versions, tool arguments and results, evidence IDs, latency, cost, and final outcome. Evaluate retrieval and factual support separately, then measure usefulness after human review effort.']}[b.dataset.detail];$('#nodeDetail').innerHTML=`<div class="label">SUPPORTING SYSTEM</div><h3>${d[0]}</h3><p>${d[1]}</p>`;});document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{state.lesson=Number(b.dataset.lesson);persist();render()});document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{state.steps[section]=Number(b.dataset.step);persist();render()});document.querySelectorAll('[data-done]').forEach(b=>b.onchange=()=>{state.done[b.dataset.done]=b.checked;persist();const focusKey=b.dataset.done;render();document.querySelector(`[data-done="${focusKey}"]`)?.focus({preventScroll:true})});if($('[data-next-lesson]'))$('[data-next-lesson]').onclick=()=>{if(state.lesson===7){location.hash='seo';return}state.lesson++;persist();render()};if($('[data-next-step]'))$('[data-next-step]').onclick=()=>{if(state.steps[section]===7){state.plan.usecase=section;persist();location.hash='kit';return}state.steps[section]++;persist();render()};if($('[data-copy-prompt]'))$('[data-copy-prompt]').onclick=()=>copy(BLUEPRINTS[section].prompt);document.querySelectorAll('[data-kit-usecase]').forEach(a=>a.onclick=()=>{state.plan.usecase=a.dataset.kitUsecase;persist()});if(section==='architecture'){paintTrace();$('#traceNext').onclick=()=>{traceStep=Math.min(trace.length-1,traceStep+1);paintTrace()};$('#traceReset').onclick=()=>{traceStep=0;paintTrace()}}if(section==='rag'){paintRag();paintChunk();for(const [id,key] of [['ragQuery','q'],['ragMode','mode'],['ragK','k']])$('#'+id).onchange=e=>{rag[key]=key==='k'?Number(e.target.value):e.target.value;paintRag()};$('#ragFresh').onchange=e=>{rag.fresh=e.target.checked;paintRag()};$('#chunkContext').onchange=paintChunk}if(section==='kit'){paintPlan();paintCost();$('#planForm').oninput=e=>{if(e.target.name){state.plan[e.target.name]=e.target.value;persist();paintPlan()}};$('#planForm').onsubmit=e=>e.preventDefault();$('#copyPlan').onclick=()=>copy(JSON.stringify(getPlan(),null,2));$('#exportPlan').onclick=exportPlan;$('#copyLoop').onclick=()=>copy(harnessCode);['calcRuns','calcApi','calcMinutes','calcRate'].forEach(id=>$('#'+id).oninput=paintCost);document.querySelectorAll('[data-release]').forEach(el=>el.onchange=()=>{state.release=state.release||{};state.release[el.dataset.release]=el.checked;persist()})}if(section==='practice'){document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{quizIndex=Number(b.dataset.case);render()});$('#caseNotes').oninput=e=>{state.notes[quizIndex]=e.target.value;persist()};document.querySelectorAll('[data-rubric]').forEach(el=>el.onchange=()=>{$('#caseScore').textContent=`${document.querySelectorAll('[data-rubric]:checked').length}/${cases[quizIndex].checks.length}`})}}
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView()};$('#exportTop').onclick=exportPlan;window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true})});render();
